export const SIMSCRIPT_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/simscript-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSimscriptStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SIMSCRIPT_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
